void require(bool value,const char *message){if(!value)throw std::runtime_error(message);}
struct Owner {
  HWND window{},edit{};
  Owner(){WNDCLASSW type{};type.lpfnWndProc=DefWindowProcW;type.hInstance=GetModuleHandleW(nullptr);type.lpszClassName=L"ScreamSeq.Matrix.TestOwner";RegisterClassW(&type);window=CreateWindowW(type.lpszClassName,L"Owned matrix fixture",WS_OVERLAPPEDWINDOW|WS_VISIBLE,0,0,1100,800,nullptr,nullptr,type.hInstance,nullptr);require(window,"Create matrix owner");ScreamSeq::Tests::ownGuiWindow(window);edit=CreateWindowW(L"EDIT",L"Unrelated retained field",WS_CHILD|WS_VISIBLE|WS_TABSTOP,0,0,200,24,window,nullptr,type.hInstance,nullptr);require(edit,"Create unrelated owner field");ScreamSeq::Tests::ownGuiWindow(edit);}
  ~Owner(){if(window)DestroyWindow(window);}
  void close(){const auto previous=window,field=edit;require(DestroyWindow(window),"Destroy matrix owner");window=edit=nullptr;require(!IsWindow(previous)&&!IsWindow(field),"Matrix owner survived destruction");}
};
