int main(){try{SetProcessDpiAwarenessContext(DPI_AWARENESS_CONTEXT_PER_MONITOR_AWARE_V2);ScreamSeq::Tests::runPrivateGui(L"ScreamSeqMatrixTest",[]{Owner owner;densityAndKeyboard(owner);retainedCopyAndStale(owner);pagingRetentionAndBounds(owner);pumpedRequestsAndInvalidData(owner);failedReadBackpressure(owner);minimumIdentityLabels(owner);owner.close();});std::cout<<"PASS matrix retained pages, stable coordinates, native density accessibility, keyboard, captured-copy guards, pumped completion, bounded minimum, theme refresh, failed-read backpressure and visible long-name identity prefixes\n";return 0;}catch(const std::exception &e){std::cerr<<e.what()<<'\n';return 1;}}
